// queues.effective-config: The effective configuration of one queue, per key, with provenance
// Generated by `pnpm nx g @app/generators:action queues.effective-config`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  EffectiveConfigSchema,
  PolicyLayerSchema,
  QUEUE_TYPES,
  SnapshotMetaSchema,
  TopologyGapsSchema,
  TopologyNameSchema,
  VhostNameSchema,
} from './topology-types.ts';

export const QueuesEffectiveConfigInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  vhost: VhostNameSchema,
  queue: TopologyNameSchema,
  /** Read the broker again instead of using a snapshot taken in the last seconds. */
  refresh: z.boolean().optional(),
});

export const QueuesEffectiveConfigOutputSchema = z.strictObject({
  vhost: VhostNameSchema,
  queue: TopologyNameSchema,
  queueType: z.enum(QUEUE_TYPES).nullable(),
  /** The lowest node version, which the registry rules were applied for; null when unreadable. */
  version: z.string().max(64).nullable(),
  mixedVersions: z.boolean(),
  layers: z.strictObject({
    user: PolicyLayerSchema,
    operator: PolicyLayerSchema,
  }),
  /**
   * Null when the queue type or a policy layer could not be decided: nothing is resolved from a
   * guess, and `layers` and `gaps` say why.
   */
  effective: EffectiveConfigSchema.nullable(),
  gaps: TopologyGapsSchema,
  snapshot: SnapshotMetaSchema,
});

export const queuesEffectiveConfig = defineAction({
  id: 'queues.effective-config',
  kind: 'query',
  summary: 'The effective configuration of one queue, per key, with provenance',
  input: QueuesEffectiveConfigInputSchema,
  output: QueuesEffectiveConfigOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({
    connectionId: input.cid,
    vhost: input.vhost,
    kind: 'queue',
    name: input.queue,
  }),
  http: { method: 'POST', path: '/connections/{cid}/effective-config/queries' },
  mcp: {
    expose: true,
    mutating: false,
    title: 'Effective configuration of a queue',
    description:
      'The value each policy key really has for one queue (argument, user policy and operator policy resolved by the registry rule), with the provenance of every input.',
  },
  cli: { command: 'effective-config get' },
  since: '1.0',
});
